274	    /**
275	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
276	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
277	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
278	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
279	     *
280	     * @param telephone the raw telephone value from the request
281	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
282	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
283	     */
284	    private String normalizeTelephone(String telephone) {
285	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
286	        String digits;
287	        if (cleaned.startsWith("+")) {
288	            digits = cleaned.substring(1);
289	        } else {
290	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
291	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
292	            digits = "61" + national;
293	        }
294	        if (!digits.matches("[0-9]{8,15}")) {
295	            throw new InvalidTelephoneException(cleaned);
296	        }
297	        return "+" + digits;
298	    }
