320	    /**
321	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
322	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
323	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
324	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
325	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
326	     *
327	     * @param address the raw address value from the request (may be {@code null})
328	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
329	     */
330	    private String normalizeAddress(String address) {
331	        if (address == null) {
332	            return "";
333	        }
334	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
335	        if (collapsed.isEmpty()) {
336	            return "";
337	        }
338	        String[] tokens = collapsed.split(" ");
339	        StringBuilder sb = new StringBuilder(collapsed.length());
340	        for (int i = 0; i < tokens.length; i++) {
341	            if (i > 0) {
342	                sb.append(' ');
343	            }
344	            sb.append(expandAddressAbbreviation(tokens[i]));
345	        }
346	        return sb.toString();
347	    }
348	
349	    /**
350	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
351	     * returns the token unchanged when it is not a recognised abbreviation.
352	     *
353	     * @param token an upper-cased whole-word address token
354	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
355	     */
356	    private String expandAddressAbbreviation(String token) {
357	        return switch (token) {
358	            case "ST" -> "STREET";
359	            case "RD" -> "ROAD";
360	            case "AVE" -> "AVENUE";
361	            default -> token;
362	        };
363	    }
364	
365	    /**
366	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
367	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
368	     *
369	     * @param telephone the normalized (E.164) telephone of the owner being created
370	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
371	     */
372	    /**
373	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
374	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
375	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
376	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
377	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
378	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
379	     *
380	     * @param city the owner's city
381	     * @param lastName the owner's last name
382	     * @return the assigned customer code
383	     */
384	    private String generateCustomerCode(String city, String lastName) {
385	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
386	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
387	        int sequence = (int) this.clinicService.findAllOwners().stream()
388	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
389	            .count() + 1;
390	        return String.format("%s-%s-%04d", city3, last3, sequence);
391	    }
392	
393	    /**
394	     * Counts how many existing owners already share the given first name and last name, compared
395	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
396	     * owner being created.
397	     *
398	     * @param firstName the first name of the owner being created
399	     * @param lastName the last name of the owner being created
400	     * @return the number of existing owners with the same first and last name (case-insensitively)
401	     */
402	    private int countNamesakes(String firstName, String lastName) {
403	        return (int) this.clinicService.findAllOwners().stream()
404	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
405	                && lastName.equalsIgnoreCase(existing.getLastName()))
406	            .count();
407	    }
408	
409	    private void rejectDuplicateTelephone(String telephone) {
410	        boolean taken = this.clinicService.findAllOwners().stream()
411	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
412	        if (taken) {
413	            throw new DuplicateTelephoneException(telephone);
414	        }
415	    }
416	
417	    /**
418	     * Rejects a create request whose owner shares both last name and address with an existing owner.
419	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
420	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
421	     * differing case) still count as the same household.
422	     *
423	     * @param lastName the last name of the owner being created
424	     * @param address the address of the owner being created
425	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
426	     */
427	    private void rejectDuplicateHousehold(String lastName, String address) {
428	        String normalizedLastName = normalizeForComparison(lastName);
429	        String normalizedAddress = normalizeForComparison(address);
430	        boolean taken = this.clinicService.findAllOwners().stream()
431	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
432	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
433	        if (taken) {
434	            throw new DuplicateHouseholdException(lastName, address);
435	        }
436	    }
437	
438	    /**
439	     * Assigns the owner being created into a shared household. When at least one existing owner has the
440	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
441	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
442	     * reused when present; otherwise a deterministic id derived from the household's last name and address
443	     * is minted, so independently created members of the same household converge on one value. When no
444	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
445	     *
446	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
447	     */
448	    private void assignHousehold(Owner owner) {
449	        String normalizedLastName = normalizeForComparison(owner.getLastName());
450	        String normalizedAddress = normalizeForComparison(owner.getAddress());
451	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
452	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
453	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
454	            .toList();
455	        if (housemates.isEmpty()) {
456	            return;
457	        }
458	        String householdId = housemates.stream()
459	            .map(Owner::getHouseholdId)
460	            .filter(id -> id != null && !id.isBlank())
461	            .findFirst()
462	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
463	        owner.setHouseholdId(householdId);
464	        for (Owner housemate : housemates) {
465	            if (!householdId.equals(housemate.getHouseholdId())) {
466	                housemate.setHouseholdId(householdId);
467	                this.clinicService.saveOwner(housemate);
468	            }
469	        }
470	    }
471	
472	    /**
473	     * Derives a stable household identifier from the normalized last name and address of a household, as
474	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
475	     * deterministic, so any owner independently joining the same household computes the same identifier.
476	     *
477	     * @param normalizedLastName the household's last name, already normalized for comparison
478	     * @param normalizedAddress the household's address, already normalized for comparison
479	     * @return a stable, shareable household identifier
480	     */
481	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
482	        String key = normalizedLastName + "|" + normalizedAddress;
483	        try {
484	            byte[] digest = MessageDigest.getInstance("SHA-256")
485	                .digest(key.getBytes(StandardCharsets.UTF_8));
486	            StringBuilder sb = new StringBuilder(digest.length * 2);
487	            for (byte b : digest) {
488	                sb.append(String.format("%02x", b));
489	            }
490	            return sb.substring(0, 16);
491	        } catch (NoSuchAlgorithmException e) {
492	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
493	        }
494	    }
495	
496	    /**
497	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
498	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
499	     * lower-cased.
500	     *
501	     * @param value the raw value to normalize (may be {@code null})
502	     * @return the normalized value, or an empty string when {@code value} is {@code null}
503	     */
504	    private String normalizeForComparison(String value) {
505	        if (value == null) {
506	            return "";
507	        }
508	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
509	    }
510	}
