/**
 * Derives an owner's locality (region) from its city using a fixed city-to-region table
 * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), returning 'UNKNOWN' for any other city.
 *
 * @param city the owner's city (may be {@code null})
 * @return the canonical region string, or 'UNKNOWN' when the city is not in the table
 */
default String locality(String city) {
    if (city == null) {
        return "UNKNOWN";
    }
    return switch (city) {
        case "Sydney" -> "NSW";
        case "Melbourne" -> "VIC";
        case "Brisbane" -> "QLD";
        default -> "UNKNOWN";
    };
}

